import type { ChartChange, ForexAction, FxInitial } from '@ss/chart-engine';
import type { CatalogEntry, Lesson } from '@ss/lesson-engine';
import catalogJson from './catalog.json';

export type ChartLesson = Lesson<FxInitial, ChartChange, ForexAction>;

/** Generated by `pnpm lessons`; validated in CI. */
export const catalog = catalogJson as CatalogEntry[];

const loaders = import.meta.glob<{ default: ChartLesson }>([
  './*.ts',
  '!./index.ts',
  '!./chapters.ts',
]);

export function loadLesson(slug: string): Promise<ChartLesson> | null {
  const load = loaders[`./${slug}.ts`];
  return load ? load().then((m) => m.default) : null;
}
